  { id: "2", email: "grace@example.com", name: "Grace", createdAt: "2026-02-11" },
];

export async function listUsers(): Promise<User[]> {
  return users;
}

export async function getUser(id: string): Promise<User | undefined> {
  return users.find((u) => u.id === id);
}

// Mirrors a WorkOS user into the local `users` list, inserting on first sign-in
// and refreshing name/email on every later one. `createdAt` is kept stable
// once a local record exists so it reflects first sign-in, not last.
function upsertUser(workosUser: WorkOSUser): User {
  const existing = users.find((u) => u.id === workosUser.id);
  const name =
    workosUser.name ??
    [workosUser.firstName, workosUser.lastName].filter(Boolean).join(" ") ||
    workosUser.email;

  const user: User = {
    id: workosUser.id,
    email: workosUser.email,
    name,
    createdAt: existing?.createdAt ?? workosUser.createdAt,
  };

  if (existing) {
    Object.assign(existing, user);
  } else {
    users.push(user);
  }
  return user;
}

// Reads the signed-in WorkOS session (if any) and syncs it into the local
// user list. Returns undefined when nobody is signed in.
export async function getCurrentUser(): Promise<User | undefined> {
  const { user } = await withAuth();
  if (!user) return undefined;
  return upsertUser(user);
}

